import sys, threading
sys.path.insert(0, "_tools")
import bench_core, bench_pool
bench_pool.record_of = lambda row, arm, label, r, cc="": {"id": row["id"], "label": label}
bench_pool.session_fields = lambda r, before: ({}, before)
def row(i):
    return {"id": f"q{i}", "kind": "good", "source": f"s{i}"}
g1, g2, g3 = [row(1), row(2), row(3)], [row(4)], [row(5)]
first_paid, s1_done, s3_started = threading.Event(), threading.Event(), threading.Event()
state = {}
def pay(x):
    with bench_core.SPEND_LOCK:
        bench_core.SPEND["usd"] += x
def runner(arm, effort, r, sid, position):
    n = r["id"]
    if n == "q1":
        pay(2.5)
        first_paid.set()
        return {"cost": 2.5}
    if n in ("q2", "q3"):
        threading.Event().wait(0.5 if n == "q2" else 0.0)
        s3_started.wait(3)
        if n == "q3":
            s1_done.set()
        return {"cost": 0.0}
    if n == "q4":
        first_paid.wait(5)
        threading.Event().wait(0.3)
        return {"cost": 0.0}
    state["s3_started_while_s1_in_flight"] = not s1_done.is_set()
    s3_started.set()
    return {"cost": 0.0}
bench_pool.run_sessions([g1, g2, g3], [("arm", "high", "lab")], 1, runner, jobs=2, cap=5.0, usd=lambda label, kind: 1.0)
flag = state.get("s3_started_while_s1_in_flight")
print("third session started while the overrun session was in flight:", flag)
sys.exit(0 if flag is not True else 1)
